parameters.jsCode:
const raw = $input.first().json.choices[0].message.content.trim();

const cleaned = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    clarity: 5,
    confidence: 5,
    relevance: 5,
    feedback: "Could not parse score. Please try again."
  };
}

return [{
  json: {
    clarity: parseInt(parsed.clarity) || 5,
    confidence: parseInt(parsed.confidence) || 5,
    relevance: parseInt(parsed.relevance) || 5,
    feedback: String(parsed.feedback) || "No feedback available."
  }
}];
